"""Closed internal-flow geometries generated by code (D-129; no binary files in the repository): a straight pipe and
the NASA TMR 2D backward-facing step channel, each a multi-solid ASCII STL whose solids are the patches.
"""

import math
from pathlib import Path

import numpy as np


def _solid(name: str, points: np.ndarray, triangles: np.ndarray) -> str:
    rows = [f"solid {name}"]
    for t in triangles:
        a, b, c = points[t[0]], points[t[1]], points[t[2]]
        n = np.cross(b - a, c - a)
        length = np.linalg.norm(n)
        n = n / length if length > 0 else n
        rows.append(f"  facet normal {n[0]:.9g} {n[1]:.9g} {n[2]:.9g}")
        rows.append("    outer loop")
        rows += [f"      vertex {p[0]:.9g} {p[1]:.9g} {p[2]:.9g}" for p in (a, b, c)]
        rows += ["    endloop", "  endfacet"]
    rows.append(f"endsolid {name}")
    return "\n".join(rows) + "\n"


def pipe_solids(diameter: float, length: float, n_theta: int = 64, axial_cell: float | None = None
                ) -> list[tuple[str, np.ndarray, np.ndarray]]:
    """A straight pipe along +x from x = 0 to ``length``: the solids "inlet" (the disc at x = 0), "wall" (the
    cylinder) and "outlet" (the disc at x = length), outward normals, sharing their rim points. ``n_theta`` points
    around; the wall's rings ``axial_cell`` apart (default: the circumferential edge)."""
    r = diameter / 2
    theta = 2 * math.pi * np.arange(n_theta) / n_theta
    ring = np.column_stack([np.zeros(n_theta), r * np.cos(theta), r * np.sin(theta)])
    edge = axial_cell or 2 * math.pi * r / n_theta
    n_x = max(1, round(length / edge))
    xs = np.linspace(0.0, length, n_x + 1)
    wall_points = np.vstack([ring + [x, 0.0, 0.0] for x in xs])
    tris = []
    for i in range(n_x):
        for j in range(n_theta):
            a, b = i * n_theta + j, i * n_theta + (j + 1) % n_theta
            c, d = a + n_theta, b + n_theta
            tris += [(a, c, b), (b, c, d)]  # outward (radial) normals
    out = [("wall", wall_points, np.array(tris))]
    for name, x, outward in (("inlet", 0.0, -1.0), ("outlet", length, 1.0)):
        points = np.vstack([[x, 0.0, 0.0], ring + [x, 0.0, 0.0]])
        fan = [(0, 1 + (j + 1) % n_theta, 1 + j) if outward < 0 else (0, 1 + j, 1 + (j + 1) % n_theta)
               for j in range(n_theta)]
        out.append((name, points, np.array(fan)))
    return out


def write_pipe(path: Path, diameter: float, length: float, n_theta: int = 64, axial_cell: float | None = None) -> Path:
    """The pipe of ``pipe_solids`` as a multi-solid ASCII STL (metres)."""
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text("".join(_solid(n, p, t) for n, p, t in pipe_solids(diameter, length, n_theta, axial_cell)))
    return path


def extruded_outline_solids(outline: list[tuple[float, float]], segment_names: list[str], y0: float, y1: float,
                            cap_name: str) -> list[tuple[str, np.ndarray, np.ndarray]]:
    """A closed polygon in x-z extruded from y0 to y1, one solid per segment name (segment i joins point i to point
    i + 1); the two caps belong to the solid ``cap_name`` (a segment's name, or a solid of their own). For the 2D mode
    (D-121): the section is cut at mid y, so the caps never reach the mesh."""
    pts = np.asarray(outline, dtype=float)
    n = len(pts)
    p0 = np.column_stack([pts[:, 0], np.full(n, y0), pts[:, 1]])
    p1 = np.column_stack([pts[:, 0], np.full(n, y1), pts[:, 1]])
    allp = np.vstack([p0, p1])
    solids: dict[str, list] = {}
    for i, name in enumerate(segment_names):
        j = (i + 1) % n
        solids.setdefault(name, []).extend([(i, j, n + j), (i, n + j, n + i)])
    import pyvista as pv

    for offset in (0, n):
        poly = pv.PolyData(allp[offset:offset + n], np.hstack([[n], np.arange(n)])).triangulate()
        solids.setdefault(cap_name, []).extend(tuple(int(v) + offset for v in tri)
                                               for tri in poly.faces.reshape(-1, 4)[:, 1:])
    return [(name, allp, np.array(t)) for name, t in solids.items()]


def write_solids(path: Path, solids) -> Path:
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text("".join(_solid(n, p, t) for n, p, t in solids))
    return path
